<script setup lang="ts">
/**
 * Markdown.Body: the parsed reply and its caret.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { markdownEndsInProse, markdownShallowestHeading, parseMarkdown } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBlocks from './MarkdownBlocks.vue'
import Text from '../structure/Text.vue'
import type { CitationSource } from './SourceList.vue'

export interface MarkdownBodyProps {
  /**
   * The markdown received so far.
   */
  source: string
  size: 'sm' | 'md'
  sources: CitationSource[]
  streaming: boolean
}

defineOptions({ name: 'MarkdownBody', inheritAttrs: false })

const props = defineProps<MarkdownBodyProps>()
const blocks = computed(() => parseMarkdown(props.source, { citations: props.sources.length }))
const shallowest = computed(() => markdownShallowestHeading(blocks.value))
</script>

<template>
  <MarkdownBlocks
    :blocks="blocks"
    :size="size"
    :sources="sources"
    :shallowest="shallowest"
    :caret="streaming"
  />
  <Text v-if="streaming && !markdownEndsInProse(blocks)" :size="size">
    <!-- caret -->
    <span :class="styles.caret" aria-hidden="true" />
  </Text>
</template>
